let generation=0;const observers=new Set(),timers=new Set(),intervals=new Set(),frames=new Set(),listeners=[];
const NativeObserver=window.MutationObserver,nativeTimeout=window.setTimeout.bind(window),nativeInterval=window.setInterval.bind(window),nativeRAF=window.requestAnimationFrame.bind(window),nativeQueue=window.queueMicrotask.bind(window),clearTimeout=window.clearTimeout.bind(window),clearInterval=window.clearInterval.bind(window),cancelRAF=window.cancelAnimationFrame.bind(window);
window.MutationObserver=class extends NativeObserver{constructor(callback){const owner=generation;super((records,observer)=>{if(owner===generation)callback(records,observer)});observers.add(this)}};
