window.setTimeout=(callback,delay,...args)=>{const owner=generation;const id=nativeTimeout(()=>{timers.delete(id);if(owner===generation)callback(...args)},delay);timers.add(id);return id};
window.setInterval=(callback,delay,...args)=>{const owner=generation;const id=nativeInterval(()=>{if(owner===generation)callback(...args)},delay);intervals.add(id);return id};
